	@Test
	void summaryAliasesPreserveBoundnessAndRollbackWithoutEscapingAsRdfIds() throws IOException {
		NativeLmdbQuerySource source = mock(NativeLmdbQuerySource.class);
		LmdbNativeValueCodec codec = mock(LmdbNativeValueCodec.class);
		RowState row = row(source);
		NativeResultCell summary = NativeResultCell.lexicalLength(4L);
		int root = row.mark();
		assertThat(row.bindSummary(0, summary)).isTrue();
		assertThat(row.boundMask()).isEqualTo(1L);
		assertThatThrownBy(() -> row.id(0)).isInstanceOf(IllegalStateException.class).hasMessageContaining("summary");
		assertThatThrownBy(() -> row.bindOrCheckTerm(0, 1L)).isInstanceOf(IllegalStateException.class);
		assertThatThrownBy(() -> row.view.getValue("source")).isInstanceOf(IllegalStateException.class);
		assertThatThrownBy(row.view::getBindingNames).isInstanceOf(IllegalStateException.class);
		assertThatThrownBy(row.view::size).isInstanceOf(IllegalStateException.class);
		assertThatThrownBy(row.view::isEmpty).isInstanceOf(IllegalStateException.class);
		int alias = row.mark();
		assertThat(ExtensionCursor.bindCopies(new CopyBinding[] { CopyBinding.slot(1, 0) }, row)).isTrue();
		assertThat(row.summaryCell(1)).isSameAs(summary);
		assertThat(row.boundMask()).isEqualTo(3L);
		assertThatThrownBy(() -> row.id(1)).isInstanceOf(IllegalStateException.class).hasMessageContaining("summary");
		assertThatThrownBy(() -> row.view.getValue("alias")).isInstanceOf(IllegalStateException.class);
		LmdbNativeScalarExpressionCompiler compiler = new LmdbNativeScalarExpressionCompiler(source, codec,
				name -> name.equals("alias") ? 1 : -1);
		LmdbNativeCompiledNumeric length = compiler.compileNumeric(
				new FunctionCall(FN.STRING_LENGTH.stringValue(), new Var("alias")));
		assertThat(length).isNotNull();
		assertThat(length.requiredMask).isEqualTo(1L << 1);
		assertThat(length.evaluator.eval(row).asValue().label()).isEqualTo("4");
		assertThatThrownBy(summary::value).isInstanceOf(IllegalStateException.class);
		verifyNoInteractions(codec);
		RowState fork = row.fork();
		row.rollback(alias);
		assertThat(row.summaryCell(1)).isNull();
		assertThat(row.summaryCell(0)).isSameAs(summary);
		assertThat(row.boundMask()).isEqualTo(1L);
		row.rollback(root);
		assertThat(row.summaryCell(0)).isNull();
		assertThat(row.boundMask()).isZero();
		assertThat(row.view.isEmpty()).isTrue();
		assertThat(fork.summaryCell(0)).isSameAs(summary);
		assertThat(fork.summaryCell(1)).isSameAs(summary);
		assertThat(fork.boundMask()).isEqualTo(3L);
		assertThat(row.bind(0, 11L)).isTrue();
		assertThat(row.id(0)).isEqualTo(11L);
	}

	@Test
	void conditionProjectionCarriesOnlyRetainedSummaryCellsAndReusedFramesClearThem() throws IOException {
		NativeLmdbQuerySource source = mock(NativeLmdbQuerySource.class);
		LmdbNativeValueCodec codec = mock(LmdbNativeValueCodec.class);
		RowState parent = row(source);
		NativeResultCell summary = NativeResultCell.lexicalLength(4L);
		int parentMark = parent.mark();
		assertThat(parent.bindSummary(0, summary)).isTrue();
		int aliasMark = parent.mark();
		assertThat(ExtensionCursor.bindCopies(new CopyBinding[] { CopyBinding.slot(1, 0) }, parent)).isTrue();
		assertThat(parent.summaryCell(0)).isSameAs(summary);
		assertThat(parent.summaryCell(1)).isSameAs(summary);

		RowState projected = parent.projectConditionInput(Set.of("alias"));
		assertThat(projected.summaryCell(0)).isNull();
		assertThat(projected.summaryCell(1)).isSameAs(summary);
		assertThat(projected.boundMask()).isEqualTo(1L << 1);
		assertThat(projected.view.hasBinding("source")).isFalse();
		assertThatThrownBy(() -> projected.id(1)).isInstanceOf(IllegalStateException.class)
				.hasMessageContaining("summary");
		assertThatThrownBy(() -> projected.view.getValue("alias")).isInstanceOf(IllegalStateException.class);
		LmdbNativeScalarExpressionCompiler compiler = new LmdbNativeScalarExpressionCompiler(source, codec,
				name -> name.equals("alias") ? 1 : -1);
		LmdbNativeCompiledNumeric length = compiler.compileNumeric(
				new FunctionCall(FN.STRING_LENGTH.stringValue(), new Var("alias")));
		assertThat(length).isNotNull();
		assertThat(length.requiredMask).isEqualTo(1L << 1);
		assertThat(length.evaluator.eval(projected).asValue().label()).isEqualTo("4");
		assertThatThrownBy(summary::value).isInstanceOf(IllegalStateException.class);

		parent.rollback(aliasMark);
		assertThat(parent.summaryCell(1)).isNull();
		assertThat(projected.summaryCell(1))
				.as("the independent projected frame must not share its parent's rollback trail")
				.isSameAs(summary);
		parent.rollback(parentMark);
		assertThat(parent.summaryCell(0)).isNull();
		assertThat(projected.summaryCell(1)).isSameAs(summary);

		RowState ordinary = row(source);
		assertThat(ordinary.bind(1, 11L)).isTrue();
		projected.copyConditionInput(ordinary, Set.of("alias"));
		assertThat(projected.summaryCell(1)).isNull();
		assertThat(projected.id(1)).isEqualTo(11L);
		assertThat(projected.boundMask()).isEqualTo(1L << 1);

		RowState unbound = row(source);
		projected.copyConditionInput(unbound, Set.of("alias"));
		assertThat(projected.summaryCell(1)).isNull();
		assertThat(projected.boundMask()).isZero();
		assertThat(projected.id(1)).isEqualTo(LmdbNativeAggregateCompiler.UNKNOWN);
		assertThat(projected.view.hasBinding("alias")).isFalse();
		verifyNoInteractions(codec);
	}

	@Test
	void projectedConditionOwnsItsExactEntryFrameWhileSharingTermsAndTypedCells() {
		NativeLmdbQuerySource store = mock(NativeLmdbQuerySource.class);
		when(store.idOf(any(Value.class), anyInt())).thenReturn(NativeLmdbQuerySource.UNKNOWN_ID);
		SyntheticValueSource root = SyntheticValueSource.forEvaluation(store);
		QueryBindingSet base = new QueryBindingSet();
		base.setBinding("visible", SimpleValueFactory.getInstance().createLiteral("first"));
		base.setBinding("hidden", SimpleValueFactory.getInstance().createLiteral("private"));
		root.executionContext().initializeQueryBase(base);
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("source", 0, "alias", 1), null);
		layout.freeze(List.of("source", "alias"));
		Set<String> retained = Set.of("visible", "alias");
		try (NativeExecutionContext owner = root.executionContext()) {
			Value term = SimpleValueFactory.getInstance().createIRI("urn:projected-condition:shared-term");
			long termId = root.internComputedValue(term);
			assertThat(root.lazyValue(termId)).as("the fixture must admit a resolvable term").isEqualTo(term);
			RowState parent = new RowState(root, layout, base);
			assertThat(NativeRowSeeder.seed(parent.slots, layout, base, root)).isTrue();
			parent.recomputeBoundMask();
			assertThat(parent.boundMask()).as("both typed lanes must start unbound").isZero();
			NativeResultCell summary = NativeResultCell.lexicalLength(17L);
			assertThat(parent.bindSummary(1, summary)).isTrue();
			RowState projected = parent.projectConditionInput(retained);
			assertThat(projected.summaryCell(1)).isSameAs(summary);
			assertThat(projected.base.getBindingNames()).containsExactly("visible");
			SyntheticValueSource selected = (SyntheticValueSource) projected.source;
			NativeExecutionContext frame = selected.executionContext();
			assertThat(frame.queryBase().getBindingNames())
					.as("independent lexical producers must not recover hidden entry names")
					.containsExactly("visible");
			assertThat(frame).as("the projected entry frame must have its own preparation cache").isNotSameAs(owner);
			assertThat(frame.queryBase().getValue("visible")).isEqualTo(base.getValue("visible"));
			assertThat(selected.lazyValue(termId)).isEqualTo(term);
			assertThat(frame.memoryScope()).isSameAs(owner.memoryScope());
			assertThat(frame.cancellation().ownerThreadId()).isEqualTo(owner.cancellation().ownerThreadId());
			assertThat(frame.getOrCreateBNode(1L, "shared"))
					.isSameAs(owner.getOrCreateBNode(1L, "shared"));
			assertThat(((SyntheticValueSource) parent.projectConditionInput(retained).source).executionContext())
					.as("the same immutable entry owner and retained domain may reuse its frame")
					.isSameAs(frame);

			QueryBindingSet secondBase = new QueryBindingSet(base);
			secondBase.setBinding("visible", SimpleValueFactory.getInstance().createLiteral("second"));
			SyntheticValueSource invocation = root.forInvocation(secondBase);
			try (NativeExecutionContext secondOwner = invocation.executionContext()) {
				RowState secondInput = new RowState(invocation, layout, secondBase);
				assertThat(NativeRowSeeder.seed(secondInput.slots, layout, secondBase, invocation)).isTrue();
				secondInput.recomputeBoundMask();
				RowState second = secondInput.projectConditionInput(retained);
				NativeExecutionContext secondFrame = ((SyntheticValueSource) second.source).executionContext();
				assertThat(secondFrame).isNotSameAs(frame);
				assertThat(secondFrame.queryBase().getBindingNames()).containsExactly("visible");
				assertThat(secondFrame.queryBase().getValue("visible")).isEqualTo(secondBase.getValue("visible"));
				assertThat(frame.queryBase().getValue("visible")).isEqualTo(base.getValue("visible"));
			}
			frame.close();
			assertThat(owner.isClosed()).isFalse();
			assertThat(root.lazyValue(termId)).as("a projected frame cannot close its shared term owner")
					.isEqualTo(term);
		}
	}

	@Test
	void projectedWorkerFramesKeepTheirOwnSourceWhileSharingTheExactQueryTermSpace() throws IOException {
		NativeLmdbQuerySource store = mock(NativeLmdbQuerySource.class);
		ParallelSource firstStore = mock(ParallelSource.class);
		ParallelSource secondStore = mock(ParallelSource.class);
		Object storedIdSpace = new Object();
		when(store.idSpace()).thenReturn(storedIdSpace);
		when(firstStore.idSpace()).thenReturn(storedIdSpace);
		when(secondStore.idSpace()).thenReturn(storedIdSpace);
		when(store.idOf(any(Value.class), anyInt())).thenReturn(NativeLmdbQuerySource.UNKNOWN_ID);
		when(store.openParallelSources(2)).thenReturn(new ParallelSource[] { firstStore, secondStore });
		SyntheticValueSource root = SyntheticValueSource.forEvaluation(store);
		QueryBindingSet base = new QueryBindingSet();
		base.setBinding("visible", SimpleValueFactory.getInstance().createLiteral("shared entry"));
		base.setBinding("hidden", SimpleValueFactory.getInstance().createLiteral("private entry"));
		root.executionContext().initializeQueryBase(base);
		try (NativeExecutionContext owner = root.executionContext()) {
			Value term = SimpleValueFactory.getInstance().createIRI("urn:projected-worker:shared-term");
			long id = root.internComputedValue(term);
			assertThat(root.lazyValue(id)).isEqualTo(term);
			ParallelSource[] opened = root.openParallelSources(2);
			assertThat(opened).hasSize(2);
			try (ParallelSource first = opened[0]; ParallelSource second = opened[1]) {
				NativeExecutionContext previous = null;
				for (int index = 0; index < opened.length; index++) {
					SyntheticValueSource worker = (SyntheticValueSource) opened[index];
					assertThat(worker.executionContext()).isSameAs(owner);
					RowState input = row(worker);
					RowState projected = input.projectConditionInput(Set.of("visible"));
					SyntheticValueSource selected = (SyntheticValueSource) projected.source;
					NativeExecutionContext frame = selected.executionContext();
					assertThat(frame).isNotSameAs(owner).isNotSameAs(previous);
					assertThat(frame.queryBase().getBindingNames()).containsExactly("visible");
					assertThat(selected.delegate).as("the projection must retain this worker's dictionary source")
							.isSameAs(index == 0 ? firstStore : secondStore);
					assertThat(selected.idSpace()).isSameAs(worker.idSpace());
					assertThat(selected.lazyValue(id)).isEqualTo(term);
					assertThat(((SyntheticValueSource) input.projectConditionInput(Set.of("visible")).source)
							.executionContext()).isSameAs(frame);
					previous = frame;
					frame.close();
					assertThat(owner.isClosed()).isFalse();
					assertThat(root.lazyValue(id)).isEqualTo(term);
				}
				verify(firstStore, never()).close();
				verify(secondStore, never()).close();
			}
		}
	}

	@Test
	void unboundAndErrorSummaryCellsCannotBecomeRdfValuesOrLeakIntoLaterSolutions() {
		for (NativeResultCell cell : List.of(NativeResultCell.unbound(NativeResultCell.Kind.LEXICAL_SUMMARY),
				NativeResultCell.error(NativeResultCell.Kind.LEXICAL_SUMMARY))) {
			RowState row = row();
			assertThat(row.bindSummary(0, cell)).isTrue();
			assertThat(row.boundMask()).isZero();
			row.recomputeBoundMask();
			assertThat(row.boundMask()).isZero();
			assertThatThrownBy(() -> row.view.hasBinding("source")).isInstanceOf(IllegalStateException.class);
			assertThatThrownBy(() -> row.replaceSlot(0, 1L)).isInstanceOf(IllegalStateException.class);
			row.rollback(0);
			assertThat(row.summaryCell(0)).isNull();
			assertThat(row.bind(0, 12L)).isTrue();
			assertThat(row.id(0)).isEqualTo(12L);
		}
	}

	private static RowState row() {
		return row(mock(NativeLmdbQuerySource.class));
	}

	private static RowState row(NativeLmdbQuerySource source) {
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("source", 0, "alias", 1), null);
		layout.freeze(List.of("source", "alias"));
		RowState row = new RowState(source, layout, EmptyBindingSet.getInstance());
		assertThat(NativeRowSeeder.seed(row.slots, layout, row.base, source)).isTrue();
		row.recomputeBoundMask();
		return row;
	}
